    private func questTitle(from answer: String) -> String {
        let trimmed = answer.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return "明天验证一个关键判断" }
        if trimmed.count <= 24 {
            return trimmed
        }
        return "\(trimmed.prefix(24))..."
    }

