            return
        }

        do {
            recentPromptRuns = try await promptRunRepository.recentPromptRuns(limit: limit)
            promptRunAuditMessage = recentPromptRuns.isEmpty ? "还没有 AI 调用记录。" : ""
        } catch {
            recentPromptRuns = []
            promptRunAuditMessage = "读取 AI 调用记录失败。"
        }
    }

