        case .standard:
            modeQuestion = "明天最应该先验证的关键判断是什么？"
        case .deep:
            modeQuestion = "这件事背后反复出现的思维模式是什么？"
        }

        questions = [
            ReflectionQuestion(
                question: modeQuestion,
                whyItMatters: "让任务从泛泛而谈变成可验证行动。"
            ),
            ReflectionQuestion(
                question: "\(todayDraft.selectedLens?.title ?? "当前透镜") 会如何改写你对这件事的判断？",
                whyItMatters: focus
            )
        ]
